def multiplication_table(n):
    table = []
    for i, _ in enumerate(range(n), start=1):
        row = []
        for j, _ in enumerate(range(n), start=1):
            row.append(i * j)
        table.append(row)

    for i, row in enumerate(table):
        for j, cell in enumerate(row):
            if j == len(row) - 1:
                print(f"{cell:4d}")
            else:
                print(f"{cell:4d}", end="")

    print("-" * (n * 4))

    for i, row in enumerate(table):
        if i % 2 == 0:
            for j, cell in enumerate(row):
                if j == 0:
                    print(f"Row {i+1}: ", end="")
                print(f"{cell} ", end="")
            print()

    return table

